import{_ as e,o as d,c as n,e as a}from"./app-6be1f847.js";const i={},l=a(`<h1 id="maven-核心知识点笔记-从依赖管理到打包模式" tabindex="-1"><a class="header-anchor" href="#maven-核心知识点笔记-从依赖管理到打包模式" aria-hidden="true">#</a> Maven 核心知识点笔记：从依赖管理到打包模式</h1><h2 id="一、依赖冲突检查命令" tabindex="-1"><a class="header-anchor" href="#一、依赖冲突检查命令" aria-hidden="true">#</a> 一、依赖冲突检查命令</h2><p>Maven 依赖冲突排查的核心工具是 <code>dependency</code> 插件，常用命令如下：</p><ol><li><p><strong>查看完整依赖树</strong></p><div class="language-Bash line-numbers-mode" data-ext="Bash"><pre class="language-Bash"><code>
mvn dependency:tree
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><p>冲突依赖会标记 <code>omitted for conflict with xxx</code></p></li><li><p>可选参数：</p><ul><li><p><code>-Dverbose</code>：显示所有依赖细节（含被排除的冲突依赖）</p></li><li><p><code>-Dincludes=groupId:artifactId</code>：过滤指定依赖（支持通配符 <code>*</code>）</p></li><li><p><code>-DoutputFile=文件名.txt</code>：将结果输出到文件</p></li></ul></li></ul></li><li><p><strong>分析依赖使用合理性</strong></p><div class="language-Bash line-numbers-mode" data-ext="Bash"><pre class="language-Bash"><code>
mvn dependency:analyze
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>输出：未使用的声明依赖、未声明但使用的依赖、冲突提示</li></ul></li><li><p><strong>生成可视化 HTML 报告</strong></p><div class="language-Bash line-numbers-mode" data-ext="Bash"><pre class="language-Bash"><code>
mvn project-info-reports:dependencies
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>报告路径：<code>target/dependency-report.html</code></li></ul></li><li><p><strong>多模块项目排查</strong></p><div class="language-Bash line-numbers-mode" data-ext="Bash"><pre class="language-Bash"><code>
# 查看指定子模块依赖树
mvn dependency:tree -pl 子模块名称 -am
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>-pl</code>：指定子模块；<code>-am</code>：同时构建依赖模块</li></ul></li></ol><h2 id="二、排除特定依赖版本的两种方式" tabindex="-1"><a class="header-anchor" href="#二、排除特定依赖版本的两种方式" aria-hidden="true">#</a> 二、排除特定依赖版本的两种方式</h2><h3 id="_1-局部排除-针对单个依赖的子依赖" tabindex="-1"><a class="header-anchor" href="#_1-局部排除-针对单个依赖的子依赖" aria-hidden="true">#</a> 1. 局部排除（针对单个依赖的子依赖）</h3><p>在目标依赖中通过 <code>&lt;exclusions&gt;</code> 标签排除，<strong>无需写版本</strong>，Maven 会排除对应 <code>groupId+artifactId</code> 的所有版本。</p><div class="language-XML line-numbers-mode" data-ext="XML"><pre class="language-XML"><code>
&lt;dependency&gt;
    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;
    &lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt;
    &lt;exclusions&gt;
        &lt;exclusion&gt;
            &lt;groupId&gt;org.apache.tomcat.embed&lt;/groupId&gt;
            &lt;artifactId&gt;tomcat-embed-core&lt;/artifactId&gt;
        &lt;/exclusion&gt;
    &lt;/exclusions&gt;
&lt;/dependency&gt;
&lt;!-- 可选：手动引入目标版本 --&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>适用场景：解决单个依赖的传递依赖冲突</li></ul><h3 id="_2-全局版本锁定-通过-dependencymanagement" tabindex="-1"><a class="header-anchor" href="#_2-全局版本锁定-通过-dependencymanagement" aria-hidden="true">#</a> 2. 全局版本锁定（通过 <code>dependencyManagement</code>）</h3><p>在父模块或当前模块的 <code>&lt;dependencyManagement&gt;</code> 中声明版本，强制项目统一使用该版本，间接排除其他版本。</p><div class="language-XML line-numbers-mode" data-ext="XML"><pre class="language-XML"><code>
&lt;dependencyManagement&gt;
    &lt;dependencies&gt;
        &lt;dependency&gt;
            &lt;groupId&gt;org.apache.commons&lt;/groupId&gt;
            &lt;artifactId&gt;commons-lang3&lt;/artifactId&gt;
            &lt;version&gt;3.12.0&lt;/version&gt;
        &lt;/dependency&gt;
    &lt;/dependencies&gt;
&lt;/dependencyManagement&gt;
&lt;!-- 子模块/当前模块引入时无需写版本 --&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><p>适用场景：多依赖、多模块的版本统一管控</p></li><li><p>优先级：低于直接声明的版本</p></li></ul><h2 id="三、maven-依赖解析规则-优先级从高到低" tabindex="-1"><a class="header-anchor" href="#三、maven-依赖解析规则-优先级从高到低" aria-hidden="true">#</a> 三、Maven 依赖解析规则（优先级从高到低）</h2><ol><li><p><strong>直接声明优先</strong>：<code>&lt;dependencies&gt;</code> 中直接写版本的依赖，优先级最高。</p></li><li><p><strong><code>dependencyManagement</code></strong> ** 锁定**：未直接声明版本时，使用该标签中锁定的版本。</p></li><li><p><strong>路径最短优先</strong>：同一依赖的不同版本，依赖路径长度更短的优先（直接依赖路径长度为 1）。</p></li><li><p><strong>路径相同则先声明优先</strong>：路径长度一致时，<code>pom.xml</code> 中先声明的依赖版本优先。</p></li><li><p><strong>主动干预规则</strong>：<code>exclusions</code>（排除依赖）和 <code>optional=true</code>（可选依赖）的优先级高于 3、4 规则。</p></li></ol><h2 id="四、父子多模块依赖解析" tabindex="-1"><a class="header-anchor" href="#四、父子多模块依赖解析" aria-hidden="true">#</a> 四、父子多模块依赖解析</h2><h3 id="_1-核心概念" tabindex="-1"><a class="header-anchor" href="#_1-核心概念" aria-hidden="true">#</a> 1. 核心概念</h3><ul><li><p><strong>聚合（</strong> <strong><code>&lt;modules&gt;</code></strong> <strong>）</strong>：父模块用于批量构建子模块，不影响依赖解析，仅控制构建顺序。</p></li><li><p><strong>继承（</strong> <strong><code>&lt;parent&gt;</code></strong> <strong>）</strong>：子模块继承父模块的配置，是多模块依赖管理的核心。</p></li></ul><h3 id="_2-核心规则" tabindex="-1"><a class="header-anchor" href="#_2-核心规则" aria-hidden="true">#</a> 2. 核心规则</h3><ol><li><p><strong>父模块 ** <strong><code>dependencyManagement</code></strong> ** 是核心</strong></p><ul><li><p>作用：统一声明依赖版本，子模块按需引入（无需写版本）。</p></li><li><p>覆盖规则：子模块直接声明版本会覆盖父模块的锁定版本。</p></li></ul></li><li><p><strong>子模块间依赖</strong></p><ul><li><p>遵循基础依赖解析规则（路径最短、先声明优先）。</p></li><li><p>可通过 <code>&lt;exclusions&gt;</code> 排除其他子模块的传递依赖。</p></li></ul></li><li><p><strong>继承的边界</strong></p><ul><li><p>子模块仅继承：<code>dependencyManagement</code>、<code>dependencies</code>、<code>properties</code>、<code>repositories</code>。</p></li><li><p>最佳实践：父模块尽量只写 <code>dependencyManagement</code> 和 <code>properties</code>，避免子模块被动引入依赖。</p></li></ul></li><li><p><strong>父模块打包方式</strong>：必须为 <code>pom</code>。</p></li></ol><h3 id="_3-多模块最佳实践" tabindex="-1"><a class="header-anchor" href="#_3-多模块最佳实践" aria-hidden="true">#</a> 3. 多模块最佳实践</h3><ul><li><p>用 <code>properties</code> 定义版本常量，便于统一升级。</p></li><li><p>避免子模块循环依赖，拆分公共逻辑为独立模块。</p></li><li><p>子模块间依赖显式声明 <code>groupId+artifactId</code>，提高可读性。</p></li></ul><h2 id="五、pom-xml-打包模式-packaging" tabindex="-1"><a class="header-anchor" href="#五、pom-xml-打包模式-packaging" aria-hidden="true">#</a> 五、<code>pom.xml</code> 打包模式（<code>&lt;packaging&gt;</code>）</h2><h3 id="_1-核心打包模式-覆盖-90-场景" tabindex="-1"><a class="header-anchor" href="#_1-核心打包模式-覆盖-90-场景" aria-hidden="true">#</a> 1. 核心打包模式（覆盖 90% 场景）</h3><table><thead><tr><th>打包模式</th><th>用途</th><th>适用场景</th><th>生命周期特点</th></tr></thead><tbody><tr><td><code>jar</code>（默认）</td><td>普通 Java 项目打包</td><td>工具类、业务模块、可依赖库</td><td>包含完整生命周期（clean → compile → test → package → install → deploy）</td></tr><tr><td><code>war</code></td><td>Web 项目打包</td><td>Spring MVC、Servlet 项目，部署到 Tomcat 等容器</td><td>包含完整生命周期，打包为符合 Web 标准的目录结构</td></tr><tr><td><code>pom</code></td><td>父/聚合模块</td><td>多模块项目的根模块，仅做配置管理</td><td>无 compile、test、package 阶段，仅保留 clean、install、deploy</td></tr><tr><td><code>ear</code></td><td>企业级应用打包</td><td>Java EE 项目，包含多个 war/jar 模块</td><td>需配合 <code>maven-ear-plugin</code>，部署到 JBoss 等 Java EE 容器</td></tr></tbody></table><h3 id="_2-扩展打包模式-特殊场景" tabindex="-1"><a class="header-anchor" href="#_2-扩展打包模式-特殊场景" aria-hidden="true">#</a> 2. 扩展打包模式（特殊场景）</h3><ul><li><p><code>maven-plugin</code>：开发自定义 Maven 插件，需 <code>maven-plugin-plugin</code>。</p></li><li><p><code>bundle</code>：OSGi 模块化项目，需 <code>maven-bundle-plugin</code>。</p></li><li><p><code>ejb</code>/<code>rar</code>：Java EE 组件项目，需对应插件支持。</p></li></ul><h3 id="_3-关键注意事项" tabindex="-1"><a class="header-anchor" href="#_3-关键注意事项" aria-hidden="true">#</a> 3. 关键注意事项</h3><ul><li><p>未指定 <code>&lt;packaging&gt;</code> 时，默认使用 <code>jar</code>。</p></li><li><p>不同打包模式对应不同的构建生命周期，需匹配对应插件。</p></li></ul><hr>`,30),t=[l];function r(c,o){return d(),n("div",null,t)}const p=e(i,[["render",r],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/java/maven/maven_basic.html.vue"]]);export{p as default};
